using System;
using System.Linq;
using System.IO;
using System.Drawing;
using System.Windows.Forms;
using System.Collections.Generic;

namespace Ara {
 public class TestBoard:Timetable {
  public void Press(Keys key){OnKeyDown(new KeyEventArgs(key));}
  public void Down(Point p){OnMouseDown(new MouseEventArgs(MouseButtons.Left,1,p.X,p.Y,0));}
  public void Drag(Point p){OnMouseMove(new MouseEventArgs(MouseButtons.Left,0,p.X,p.Y,0));}
  public void Up(Point p){OnMouseUp(new MouseEventArgs(MouseButtons.Left,1,p.X,p.Y,0));}
  public void Wheel(int delta){OnMouseWheel(new MouseEventArgs(MouseButtons.None,0,200,200,delta));}
  public void DropItem(CellBlock b,int lane,int index){var r=CellRect(lane,index);Point point=PointToScreen(new Point(r.X+r.Width/2,r.Y+r.Height/2));var data=new DataObject();data.SetData(typeof(CellBlock),b);OnDragDrop(new DragEventArgs(data,0,point.X,point.Y,DragDropEffects.Copy,DragDropEffects.Copy));}
 }
 public static class GridTests {
  static void Assert(bool yes,string why){if(!yes)throw new Exception(why);}
  static State New(){var s=State.Legacy();GridEngine.Ensure(s,s.GetDay(new DateTime(2026,10,14)));return s;}
  static Day D(State s){return s.Days[0];}
  static CellBlock Record(Day d,string meal,DateTime start,int count=3){var b=new CellBlock{Id=Guid.NewGuid().ToString("N"),Start=start,Count=count,Name=meal,Category="식사",MealId=meal,Score=2};d.Records.Add(b);return b;}
  static void Consistent(GridPlan p){for(int i=1;i<p.Blocks.Count;i++)Assert(p.Blocks[i].Start>=p.Blocks[i-1].End,"overlap");}
  static Point Center(TestBoard board,int lane,int index){var r=board.CellRect(lane,index);return new Point(r.X+r.Width/2,r.Y+r.Height/2);}
  public static void Run(Action<string,Action> check,string dir){
   check("grid: generated upper plan is contiguous on ten-minute boundaries",()=>{var s=New();var p=GridEngine.Build(s,D(s));Assert(p.Blocks.Count==15,"count");Assert(p.Blocks.All(x=>x.Start.Minute%10==0&&x.Count>0),"snap");Assert(p.Blocks.Last().End==D(s).Wake.AddMinutes(750),"end");Consistent(p);});
   check("grid: optional activity text, category-only records and weighted scores",()=>{var s=New();D(s).Records.Add(new CellBlock{Id="a",Start=D(s).Wake,Count=12,Name="",Category="학습",Score=3});D(s).Records.Add(new CellBlock{Id="b",Start=D(s).Wake.AddHours(3),Count=2,Category="휴식",Score=-1.5m});GridEngine.Validate(D(s));Assert(GridEngine.Total(D(s))==33,"3*12-1.5*2");});
   check("grid: editing middle cells preserves both outside fragments and scores",()=>{var list=new List<CellBlock>{new CellBlock{Id="a",Start=new DateTime(2026,10,14,9,0,0),Count=12,Category="작업",Score=2}};GridEngine.SetRange(list,new CellBlock{Id="b",Start=new DateTime(2026,10,14,9,30,0),Count=3,Category="학습",Score=5});Assert(list.Count==3&&list.Sum(x=>x.Count*x.Score)==33,"score fragments");});
   check("grid: clearing selected cells subtracts only those cell scores",()=>{var s=New();D(s).Records.Add(new CellBlock{Id="a",Start=D(s).Wake,Count=6,Category="작업",Score=4});GridEngine.ClearRange(D(s).Records,D(s).Wake.AddMinutes(20),2);GridEngine.Validate(D(s));Assert(GridEngine.Total(D(s))==16&&D(s).Records.Count==2,"clear");});
   check("grid: actual meal category and Korean names identify the matching meal",()=>{var s=New();var p=GridEngine.Build(s,D(s));var r=new CellBlock{Id="r",Start=D(s).Wake.AddHours(5),Count=3,Category="식사",Name="점심 먹음"};Assert(GridEngine.DetectMeal(D(s),p,r)=="b6","lunch");r.Name="";r.Start=p.Blocks.Find(x=>x.MealId=="b10").Start;Assert(GridEngine.DetectMeal(D(s),p,r)=="b10","nearest");Assert(GridEngine.MealName("요거트 먹기")&&GridEngine.MealName("밥 먹음")&&!GridEngine.MealName("코딩"),"names");});
   check("grid: early actual meal pulls upper future plans forward only",()=>{var s=New();var original=GridEngine.Build(s,D(s));var meal=original.Blocks.Find(x=>x.MealId=="b1");Record(D(s),"b1",meal.Start.AddMinutes(-20));var p=GridEngine.Build(s,D(s));Assert(p.Blocks.Find(x=>x.TemplateId=="b2").Start==original.Blocks.Find(x=>x.TemplateId=="b2").Start.AddMinutes(-20),"forward");Assert(D(s).Records[0].Start==meal.Start.AddMinutes(-20),"fact");Consistent(p);});
   check("grid: late meal reflows upper plan and spends buffers without editing actual facts",()=>{var s=New();var p=GridEngine.Build(s,D(s));Record(D(s),"b1",p.Blocks.Find(x=>x.MealId=="b1").Start.AddMinutes(140));var before=D(s).Records[0].Copy();p=GridEngine.Build(s,D(s));Assert(p.Saved==140&&p.Overflow==0,"recovered "+p.Saved);Assert(D(s).Records[0].Start==before.Start&&D(s).Records[0].Count==before.Count,"facts");Consistent(p);});
   check("grid: multiple actual meal anchors and actual duration remain authoritative",()=>{var s=New();var p=GridEngine.Build(s,D(s));Record(D(s),"b1",p.Blocks.Find(x=>x.MealId=="b1").Start.AddMinutes(20),4);Record(D(s),"b6",p.Blocks.Find(x=>x.MealId=="b6").Start.AddMinutes(40),3);p=GridEngine.Build(s,D(s));Assert(p.Blocks.Find(x=>x.MealId=="b1").Count==4,"duration");foreach(var r in D(s).Records)Assert(p.Blocks.Find(x=>x.MealId==r.MealId).Start==r.Start,"anchor");Consistent(p);});
   check("grid: moving an actual meal preserves score and updates upper plan",()=>{var s=New();var p=GridEngine.Build(s,D(s));var b=Record(D(s),"b1",p.Blocks.Find(x=>x.MealId=="b1").Start);decimal total=GridEngine.Total(D(s));GridEngine.Move(D(s).Records,b.Id,b.Start.AddMinutes(20));p=GridEngine.Build(s,D(s));Assert(p.Blocks.Find(x=>x.MealId=="b1").Start==b.Start&&GridEngine.Total(D(s))==total,"moved meal");});
   check("grid: clearing actual meal restores generated upper plan without drift",()=>{var s=New();var before=GridEngine.Build(s,D(s));Record(D(s),"b1",before.Blocks.Find(x=>x.MealId=="b1").Start.AddMinutes(80));GridEngine.Build(s,D(s));D(s).Records.Clear();var after=GridEngine.Build(s,D(s));Assert(before.Blocks.Last().End==after.Blocks.Last().End&&before.Blocks[2].Start==after.Blocks[2].Start,"restore");});
   check("grid: clearing beginning of meal retains automatic recognition of remaining cells",()=>{var s=New();var p=GridEngine.Build(s,D(s));var original=p.Blocks.Find(x=>x.MealId=="b1");Record(D(s),"b1",original.Start);GridEngine.ClearRange(D(s).Records,original.Start,1);p=GridEngine.Build(s,D(s));Assert(D(s).Records.Single().MealId=="b1"&&p.Blocks.Find(x=>x.MealId=="b1").Start==original.Start.AddMinutes(10),"remaining meal");});
   check("grid: occupied destination rejects move without changing either record",()=>{var s=New();D(s).Records.Add(new CellBlock{Id="a",Start=D(s).Wake,Count=3,Category="작업"});D(s).Records.Add(new CellBlock{Id="b",Start=D(s).Wake.AddHours(1),Count=3,Category="학습"});bool rejected=false;try{GridEngine.Move(D(s).Records,"a",D(s).Wake.AddMinutes(50));}catch(InvalidOperationException){rejected=true;}Assert(rejected&&D(s).Records[0].Start==D(s).Wake,"collision");});
   check("grid: past-midnight records preserve dates and daily ownership of score",()=>{var s=New();var d=D(s);d.Wake=d.Wake.Date.AddHours(18);d.GridBase=GridEngine.Generate(s,d);d.Records.Add(new CellBlock{Id="a",Start=d.Wake.Date.AddDays(1).AddHours(1),Count=6,Category="학습",Score=2});var path=Path.Combine(dir,"grid-roundtrip.json");new Store(path).Save(s);var loaded=new Store(path).Load();Assert(GridEngine.Total(loaded.Days[0])==12&&loaded.Days[0].Records[0].Start.Date==d.Wake.Date.AddDays(1),"overnight");Assert(GridEngine.Total(loaded.GetDay(d.Wake.AddDays(1)))==0,"not duplicated");});
   check("grid: old-version starts migrate and original actual timestamps remain intact",()=>{var s=State.Legacy();var d=s.GetDay(new DateTime(2026,10,14));d.Actual["b1"]=d.Wake.AddMinutes(30);GridEngine.Ensure(s,d);Assert(d.Records.Single().MealId=="b1"&&d.Actual["b1"]==d.Wake.AddMinutes(30),"migration");});
   check("grid: duplicate meal and out-of-range records reject malformed backups",()=>{var s=New();Record(D(s),"b1",D(s).Wake.AddHours(1));Record(D(s),"b1",D(s).Wake.AddHours(2));bool invalid=false;try{GridEngine.Validate(D(s));}catch(InvalidDataException){invalid=true;}Assert(invalid,"duplicate");});
   check("grid: already-recorded meals do not send plan reminders again",()=>{var s=New();var p=GridEngine.Build(s,D(s));var meal=p.Blocks.Find(x=>x.MealId=="b1");Record(D(s),"b1",meal.Start);var plan=GridEngine.AsPlan(s,D(s),GridEngine.Build(s,D(s)));Assert(!Reminders.Due(s,D(s),plan,meal.Start).Any(x=>x.Block.Kind=="meal"),"already recorded");});
   check("pointer: multi-hour selection continues across rows in both directions",()=>{using(var form=new Form{Size=new Size(900,650)})using(var board=new TestBoard()){form.Controls.Add(board);form.Show();Application.DoEvents();board.SetData(new DateTime(2026,10,14),new List<CellBlock>(),new List<CellBlock>());board.SimulateDrag(1,51,72,true);Assert(board.Selection.Lane==1&&board.Selection.First==51&&board.Selection.Last==72&&board.Selection.Count==22,"forward");board.SimulateDrag(0,80,47,true);Assert(board.Selection.Lane==0&&board.Selection.First==47&&board.Selection.Last==80,"backward");form.Close();}});
   check("pointer: crossing the other lane never changes selection lane",()=>{using(var form=new Form{Size=new Size(900,650)})using(var board=new TestBoard()){form.Controls.Add(board);form.Show();Application.DoEvents();board.SetData(new DateTime(2026,10,14),new List<CellBlock>(),new List<CellBlock>());board.Jump(board.Origin.AddHours(8));board.ForceSelection=true;board.Down(Center(board,0,48));board.Drag(Center(board,1,53));board.Up(Center(board,1,53));Assert(board.Selection.Lane==0&&board.Selection.Count==6,"plan locked");board.Down(Center(board,1,49));board.Drag(Center(board,0,53));board.Up(Center(board,0,53));Assert(board.Selection.Lane==1&&board.Selection.Count==5,"actual locked");form.Close();}});
   check("pointer: assigned blocks request a whole-block move in their own lane",()=>{using(var form=new Form{Size=new Size(900,650)})using(var board=new TestBoard()){form.Controls.Add(board);form.Show();Application.DoEvents();var origin=new DateTime(2026,10,14);var record=new CellBlock{Id="block",Start=origin.AddHours(8),Count=3,Category="학습",Score=2};board.SetData(origin,new List<CellBlock>(),new List<CellBlock>{record});MoveRequest move=null;board.MoveRequested+=(s,e)=>move=e;board.SimulateDrag(1,49,61,false);Assert(move!=null&&move.Lane==1&&move.Id=="block"&&move.Start==origin.AddHours(10),"whole-block move");form.Close();}});
   check("pointer: plan block copies into selected actual range without moving plan",()=>{using(var form=new Form{Size=new Size(900,650)})using(var board=new TestBoard()){form.Controls.Add(board);form.Show();Application.DoEvents();var origin=new DateTime(2026,10,14);var plan=new CellBlock{Id="planned",Start=origin.AddHours(8),Count=3,Category="식사",Name="1끼니",MealId="b1"};board.SetData(origin,new List<CellBlock>{plan},new List<CellBlock>());board.SetSelection(new CellSelection{Lane=1,First=51,Last=65});board.Jump(origin.AddHours(8));PaletteRequest copy=null;MoveRequest move=null;board.PaletteRequested+=(s,e)=>copy=e;board.MoveRequested+=(s,e)=>move=e;board.Down(Center(board,0,49));board.Drag(Center(board,1,52));board.Up(Center(board,1,52));Assert(copy!=null&&copy.Selection.Lane==1&&copy.Selection.First==51&&copy.Selection.Count==15&&copy.Item.Name=="1끼니"&&move==null&&plan.Start==origin.AddHours(8),"plan copy selection");form.Close();}});
   check("pointer: same-lane block movement can span midnight",()=>{using(var form=new Form{Size=new Size(900,650)})using(var board=new TestBoard()){form.Controls.Add(board);form.Show();Application.DoEvents();var origin=new DateTime(2026,10,14);board.SetData(origin,new List<CellBlock>{new CellBlock{Id="p",Start=origin.AddHours(23),Count=6,Category="학습"}},new List<CellBlock>());MoveRequest move=null;board.MoveRequested+=(s,e)=>move=e;board.SimulateDrag(0,138,150,false);Assert(move!=null&&move.Lane==0&&move.Start==origin.AddDays(1).AddHours(1),"midnight");form.Close();}});
  }
 }
}
